@Component("quote-handler")
@ProcessingGroup("quote-processing-group")
public class QuoteEventHandler {
	
	// core constructor
	QuoteEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateQuoteEvent
     */
    @EventHandler
    public void handle( CreateQuoteEvent event) {
        entityManager.persist(new Quote(event.getQuoteId(), event.getQuoteNumber(), event.getTotalPremium(), event.getRatingDate(), event.getAsBound(), event.getApplication(), event.getUnderwritingDecisions(), event.getPolicy()));
    }

    /*
     * @param	event UpdateQuoteEvent
     */
    @EventHandler
    public Quote handle( UpdateQuoteEvent event) {
    	entityManager.merge(new Quote(event.getQuoteId(), event.getQuoteNumber(), event.getTotalPremium(), event.getRatingDate(), event.getAsBound(), event.getApplication(), event.getUnderwritingDecisions(), event.getPolicy()));
    }
    
    /*
     * @param	event DeleteQuoteEvent
     */
    @EventHandler
    public void on( DeleteQuoteEvent event) {
    	Quote entity = new Quote();
   
    	// ------------------------------------------
    	// apply the QuoteId
    	// ------------------------------------------
    	entity.setQuoteId( event.getQuoteId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final QuoteRepository quoteEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(QuoteEventHandler.class.getName());

}
